{
  "name": "规则任务组件",
  "name_en": "Rule Task Component",
  "manufacturer": "",
  "description": "这是一个非物理的软件组件，用于实验相关的数据处理与集群任务编排。它负责在规则触发前准备元数据和提交参数、提交规则任务、跟踪任务进度、等待任务完成，并在结束后执行清理。结合派生类可用于配方处理、本地化分析以及实时数据完成后的后处理流程，也可配合监视器在 Jupyter 笔记本中显示规则进度。",
  "description_en": "This is a non-physical software component for experiment-related data processing and cluster task orchestration. It prepares metadata and submission arguments before a rule is triggered, posts rule tasks, tracks progress, waits for completion, and performs cleanup afterward. Via derived classes it can support recipe processing, localization analysis, and end-of-data post-processing, and it can be used with watchers to display rule progress in Jupyter notebooks.",
  "actions": [
    {
      "action_name": "auto-prepare",
      "description": "准备规则触发前所需的元数据和提交参数。",
      "description_en": "Prepare metadata and submission arguments needed before the rule is triggered."
    },
    {
      "action_name": "output_files",
      "description": "获取输出文件。",
      "description_en": "get output files"
    },
    {
      "action_name": "complete",
      "description": "获取规则是否完成。",
      "description_en": "get whether the rule is complete"
    },
    {
      "action_name": "data_complete",
      "description": "获取底层数据是否完成。",
      "description_en": "get whether the underlying data is complete"
    },
    {
      "action_name": "auto-on_data_complete",
      "description": "在底层数据完成后执行收尾处理，例如写入采集结束事件。",
      "description_en": "Run end-of-data handling when the underlying data is complete, for example writing end-of-acquisition events."
    },
    {
      "action_name": "get_new_tasks",
      "description": "获取新产生的任务范围。",
      "description_en": "get newly available task ranges"
    },
    {
      "action_name": "auto-push",
      "description": "创建所需文件并提交规则；如果数据尚未全部可用，则轮询并继续释放新任务。",
      "description_en": "Create required files and post the rule; if all data is not yet available, poll and continue releasing new tasks."
    },
    {
      "action_name": "auto-cleanup",
      "description": "清理规则执行相关的资源或临时内容。",
      "description_en": "Clean up resources or temporary content related to rule execution."
    },
    {
      "action_name": "auto-status",
      "description": "查询规则当前状态。",
      "description_en": "Query the current status of the rule."
    },
    {
      "action_name": "auto-join",
      "description": "等待规则相关任务结束。",
      "description_en": "Wait for rule-related tasks to finish."
    },
    {
      "action_name": "auto-watch",
      "description": "监视规则进度并持续更新显示或状态。",
      "description_en": "Watch rule progress and continuously update the display or status."
    }
  ],
  "tag_hints": [
    "rule-based workflow",
    "cluster job orchestration",
    "Jupyter progress monitoring",
    "metadata preparation",
    "recipe execution",
    "localization analysis tasks",
    "task polling"
  ]
}

